import {memo,useLayoutEffect,useMemo} from "react";import {filterTickets,type Ticket} from "./reportModel";
// Test zaznaczenia: po przeniesieniu wyboru z #1 na #2 commitują tylko te dwa wiersze.
export const Row=memo(function Row({ticket,selected,onSelect,onCommit}:{ticket:Ticket;selected:boolean;onSelect:(id:number)=>void;onCommit?:(id:number)=>void}){useLayoutEffect(()=>{onCommit?.(ticket.id);});return <tr aria-selected={selected}><td><button type="button" aria-pressed={selected} onClick={()=>onSelect(ticket.id)}>{"Zaznacz #"+ticket.id}</button></td><td>{ticket.title}</td><td>{ticket.assignee??"—"}</td></tr>;});
