export const FilteredTable=memo(function FilteredTable({tickets,query,assignee,selectedId,onSelect,onRowCommit,onTableCommit}:{tickets:readonly Ticket[];query:string;assignee:string;selectedId:number|null;onSelect:(id:number)=>void;onRowCommit?:(id:number)=>void;onTableCommit?:(query:string)=>void}){const visible=useMemo(()=>filterTickets(tickets,query,assignee),[tickets,query,assignee]);useLayoutEffect(()=>{onTableCommit?.(query);});return <section><h2>Tickety</h2><p>Wyniki: {visible.length}</p><table><thead><tr><th>Wybór</th><th>Tytuł</th><th>Osoba</th></tr></thead><tbody>{visible.map(ticket=><Row key={ticket.id} ticket={ticket} selected={selectedId===ticket.id} onSelect={onSelect} onCommit={onRowCommit}/>)}</tbody></table>{visible.length===0&&<p>Brak pasujących ticketów.</p>}</section>;});

