import {lazy,memo,Suspense,useCallback,useDeferredValue,useLayoutEffect,useMemo,useState,type ComponentType} from "react";import {FilteredTable} from "./FilteredTable";import {VirtualActivityList} from "./VirtualActivityList";import {statsByStatus,type Ticket,type Activity,type Counts} from "./reportModel";export type Commit={query:string;deferredQuery:string;pending:boolean};export type ReportsProps={tickets:readonly Ticket[];activity:readonly Activity[];computeStats?:typeof statsByStatus;onScreenCommit?:(value:Commit)=>void;onRowCommit?:(id:number)=>void;onTableCommit?:(query:string)=>void};const ActivityPanel=memo(VirtualActivityList);
