import {act,fireEvent,render,screen,waitFor} from "@testing-library/react";import {afterEach,beforeEach,expect,test,vi} from "vitest";import {makeData,statsByStatus} from "./reportModel";import {ReportsScreen,createReportsScreen,type Commit} from "./ReportsScreen";import {ReportsBaseline} from "./ReportsBaseline";
const heights=new Map<number,number>();const observers:newObserver[]=[];class newObserver{targets=new Set<Element>();constructor(private callback:ResizeObserverCallback){observers.push(this);}observe(target:Element){this.targets.add(target);}unobserve(target:Element){this.targets.delete(target);}disconnect(){this.targets.clear();}resize(){this.callback([...this.targets].map(target=>({target,borderBoxSize:[{blockSize:(target as HTMLElement).offsetHeight,inlineSize:600}]})) as unknown as ResizeObserverEntry[],this as unknown as ResizeObserver);}}
beforeEach(()=>{heights.clear();observers.length=0;vi.stubGlobal("ResizeObserver",newObserver);vi.spyOn(HTMLElement.prototype,"clientHeight","get").mockImplementation(function(this:HTMLElement){return this.dataset.viewport?480:0;});vi.spyOn(HTMLElement.prototype,"clientWidth","get").mockReturnValue(600);vi.spyOn(HTMLElement.prototype,"offsetHeight","get").mockImplementation(function(this:HTMLElement){return this.tagName==="LI"?heights.get(Number(this.dataset.index))??(Number(this.dataset.index)%3===0?88:44):480;});vi.spyOn(HTMLElement.prototype,"scrollHeight","get").mockImplementation(function(this:HTMLElement){return this.dataset.viewport?parseFloat((this.firstElementChild as HTMLElement)?.style.height??"0"):0;});Object.defineProperty(HTMLElement.prototype,"scrollTo",{configurable:true,value:function(this:HTMLElement,options:ScrollToOptions){this.scrollTop=options.top??0;this.dispatchEvent(new Event("scroll"));}});});afterEach(()=>{vi.unstubAllGlobals();vi.restoreAllMocks();});

